class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:
        out, path, used = [], [], [False] * len(nums)
        def dfs():
            if len(path) == len(nums): out.append(path.copy()); return
            for i, value in enumerate(nums):
                if used[i]: continue
                used[i] = True; path.append(value); dfs(); path.pop(); used[i] = False
        dfs(); return out

import java.util.*;

class Solution {
    public List<List<Integer>> permute(int[] nums) { List<List<Integer>> out=new ArrayList<>(); dfs(nums,new boolean[nums.length],new ArrayList<>(),out); return out; }
    private void dfs(int[] a,boolean[] used,List<Integer> path,List<List<Integer>> out){
        if(path.size()==a.length){out.add(new ArrayList<>(path));return;}
        for(int i=0;i<a.length;i++)if(!used[i]){used[i]=true;path.add(a[i]);dfs(a,used,path,out);path.remove(path.size()-1);used[i]=false;}
    }
}

