        nums.sort(); out=[]; path=[]; used=[False]*len(nums)
        def dfs():
            if len(path)==len(nums):out.append(path.copy());return
            for i,v in enumerate(nums):
                if used[i] or (i>0 and nums[i]==nums[i-1] and not used[i-1]):continue
