class Solution:
    def solveNQueens(self, n: int) -> List[List[str]]:
        out=[]; cols=set(); diag1=set(); diag2=set(); placement=[]
        def dfs(r):
            if r==n:
                out.append(['.'*c+'Q'+'.'*(n-c-1) for c in placement]);return
            for c in range(n):
                if c in cols or r-c in diag1 or r+c in diag2:continue
                cols.add(c);diag1.add(r-c);diag2.add(r+c);placement.append(c)
                dfs(r+1)
                placement.pop();cols.remove(c);diag1.remove(r-c);diag2.remove(r+c)
        dfs(0);return out

import java.util.*;

class Solution {
    public List<List<String>> solveNQueens(int n) { List<List<String>> out=new ArrayList<>();dfs(0,n,new int[n],new boolean[n],new boolean[2*n],new boolean[2*n],out);return out; }
    private void dfs(int r,int n,int[] pos,boolean[] cols,boolean[] d1,boolean[] d2,List<List<String>> out){
        if(r==n){List<String>b=new ArrayList<>();for(int c:pos)b.add(".".repeat(c)+"Q"+".".repeat(n-c-1));out.add(b);return;}
        for(int c=0;c<n;c++){int a=r-c+n,b=r+c;if(cols[c]||d1[a]||d2[b])continue;pos[r]=c;cols[c]=d1[a]=d2[b]=true;dfs(r+1,n,pos,cols,d1,d2,out);cols[c]=d1[a]=d2[b]=false;}
    }
}

class Solution:
    def totalNQueens(self, n: int) -> int:
        cols=set();d1=set();d2=set()
        def dfs(r):
            if r==n:return 1
            total=0
            for c in range(n):
                if c in cols or r-c in d1 or r+c in d2:continue
                cols.add(c);d1.add(r-c);d2.add(r+c)
                total+=dfs(r+1)
                cols.remove(c);d1.remove(r-c);d2.remove(r+c)
            return total
        return dfs(0)

class Solution {
    public int totalNQueens(int n) { return dfs(0,n,new boolean[n],new boolean[2*n],new boolean[2*n]); }
    private int dfs(int r,int n,boolean[] cols,boolean[] d1,boolean[] d2){
        if(r==n)return 1;int total=0;
        for(int c=0;c<n;c++){int a=r-c+n,b=r+c;if(cols[c]||d1[a]||d2[b])continue;cols[c]=d1[a]=d2[b]=true;total+=dfs(r+1,n,cols,d1,d2);cols[c]=d1[a]=d2[b]=false;}
        return total;
    }
}

