class Solution:
    def spiralOrder(self, matrix: List[List[int]]) -> List[int]:
        top,bottom,left,right=0,len(matrix)-1,0,len(matrix[0])-1;out=[]
        while top<=bottom and left<=right:
            for c in range(left,right+1):out.append(matrix[top][c])
            top+=1
            for r in range(top,bottom+1):out.append(matrix[r][right])
            right-=1
            if top<=bottom:
                for c in range(right,left-1,-1):out.append(matrix[bottom][c])
                bottom-=1
            if left<=right:
                for r in range(bottom,top-1,-1):out.append(matrix[r][left])
                left+=1
        return out

import java.util.*;

class Solution {
    public List<Integer> spiralOrder(int[][] matrix) {
        List<Integer> out=new ArrayList<>();int top=0,bottom=matrix.length-1,left=0,right=matrix[0].length-1;
        while(top<=bottom&&left<=right){for(int c=left;c<=right;c++)out.add(matrix[top][c]);top++;for(int r=top;r<=bottom;r++)out.add(matrix[r][right]);right--;if(top<=bottom){for(int c=right;c>=left;c--)out.add(matrix[bottom][c]);bottom--;}if(left<=right){for(int r=bottom;r>=top;r--)out.add(matrix[r][left]);left++;}}
        return out;
    }
}

