class Solution {
    public int[][] merge(int[][] intervals) {
        Arrays.sort(intervals,Comparator.comparingInt(a->a[0]));List<int[]> out=new ArrayList<>();
        for(int[] in:intervals){if(out.isEmpty()||in[0]>out.get(out.size()-1)[1])out.add(in.clone());else out.get(out.size()-1)[1]=Math.max(out.get(out.size()-1)[1],in[1]);}
        return out.toArray(new int[out.size()][]);
    }
}

