class Solution:
    def getPermutation(self, n: int, k: int) -> str:
        numbers=list(range(1,n+1));factorial=[1]*(n+1)
        for i in range(1,n+1):factorial[i]=factorial[i-1]*i
        k-=1;out=[]
        for size in range(n,0,-1):
            index,k=divmod(k,factorial[size-1]);out.append(str(numbers.pop(index)))
        return ''.join(out)

import java.util.*;

class Solution {
    public String getPermutation(int n,int k) {
        List<Integer> nums=new ArrayList<>();for(int i=1;i<=n;i++)nums.add(i);
        int[] fact=new int[n+1];fact[0]=1;for(int i=1;i<=n;i++)fact[i]=fact[i-1]*i;
        k--;StringBuilder out=new StringBuilder();
        for(int size=n;size>0;size--){int idx=k/fact[size-1];k%=fact[size-1];out.append(nums.remove(idx));}
        return out.toString();
    }
}
